1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  cursed?: boolean;
8	}
9	
10	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
11	  sword: 100,
12	  amulet: 60,
13	  staff: 80,
14	  potion: 40,
15	};
16	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
17	const COMPONENT_BASE_PREMIUM = 25;
18	const BLOCK_SIZE = 3;
19	const BLOCK_BASE_PREMIUM = 60;
20	const CURSE_SURCHARGE_RATE = 0.5;
21	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
22	const PROCESSING_FEE = 5;
23	
24	function isComponent(item: Item): boolean {
25	  return COMPONENT_TYPES.has(item.type);
26	}
27	
28	function isMainItem(item: Item): boolean {
29	  return !isComponent(item);
30	}
31	
32	function mainItemBasePremium(item: Item): number {
33	  return MAIN_ITEM_BASE_PREMIUMS[item.type];
34	}
35	
36	function alikeGroupBasePremium(count: number): number {
37	  return count === BLOCK_SIZE
38	    ? BLOCK_BASE_PREMIUM
39	    : count * COMPONENT_BASE_PREMIUM;
40	}
41	
42	/** Components are "alike" when they are of exactly the same type. */
43	function alikeKey(component: Item): string {
44	  return component.type;
45	}
46	
47	function componentsBasePremium(components: Item[]): number {
48	  const countsPerAlikeGroup = new Map<string, number>();
49	  for (const component of components) {
50	    const key = alikeKey(component);
51	    countsPerAlikeGroup.set(key, (countsPerAlikeGroup.get(key) ?? 0) + 1);
52	  }
53	  return [...countsPerAlikeGroup.values()].reduce(
54	    (total, count) => total + alikeGroupBasePremium(count),
55	    0,
56	  );
57	}
58	
59	/**
60	 * Item-specific modifiers apply to the base premium of the affected item and
61	 * are added to it, never multiplied onto it.
62	 */
63	function itemSpecificModifiers(item: Item, itemBasePremium: number): number {
64	  return item.cursed === true ? itemBasePremium * CURSE_SURCHARGE_RATE : 0;
65	}
66	
67	function mainItemPremium(item: Item): number {
68	  const base = mainItemBasePremium(item);
69	  return base + itemSpecificModifiers(item, base);
70	}
71	
72	function mainItemsBasePremium(mainItems: Item[]): number {
73	  return mainItems.reduce((total, item) => total + mainItemPremium(item), 0);
74	}
75	
76	function policyBasePremiumFor(items: Item[]): number {
77	  return (
78	    mainItemsBasePremium(items.filter(isMainItem)) +
79	    componentsBasePremium(items.filter(isComponent))
80	  );
81	}
82	
83	function roundInMHPCOsFavour(premium: number): number {
84	  return Math.ceil(premium);
85	}
86	
87	/**
88	 * Policy-wide modifiers apply to the policy base premium (the sum of all item
89	 * base premiums) and are added to it, never multiplied onto it.
90	 */
91	function policyWideModifiers(policyBasePremium: number): number {
92	  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
93	}
94	
95	export function quote(customer: Customer, items: Item[]): number {
96	  const policyBasePremium = policyBasePremiumFor(items);
97	  const premium =
98	    policyBasePremium + policyWideModifiers(policyBasePremium) + PROCESSING_FEE;
99	  return roundInMHPCOsFavour(premium);
100	}
