/**
 * The sum of every item's premium *after* its own item-specific modifiers.
 *
 * NOTE: the specification calls the sum of the unmodified price-list figures
 * the "policy base premium" (cursed sword + plain amulet -> 160 G, with the
 * 50 G curse surcharge added on top). This function deliberately does NOT
 * return that figure: the currently active behaviour applies the first
 * insurance surcharge to the modified amount. See policyWideModifiers.
 */
function itemsPremium(items: Item[]): number {
  return (
    mainItemsPremium(items.filter(isMainItem)) +
    componentsBasePremium(items.filter(isComponent))
  );
}

