/**
 * Policy-wide modifiers are added to their base, never multiplied onto it.
 *
 * OPEN QUESTION (not settled by any active test): the specification states
 * that policy-wide modifiers apply to the *policy base premium* -- the sum of
 * the unmodified item base premiums -- and its integration example makes that
 * concrete: a cursed sword at 0 years costs 165 G (100 base + 50 curse + 10
 * first insurance + 5 fee), i.e. the first insurance surcharge is 10 % of 100,
 * not of 150. The base passed in here is the item premium *including*
 * item-specific modifiers, which yields 170 G instead. Resolve when the first
 * insurance / integration behaviours are activated.
 */
function policyWideModifiers(base: number): number {
  return base * FIRST_INSURANCE_SURCHARGE_RATE;
}

export function quote(customer: Customer, items: Item[]): number {
  const base = itemsPremium(items);
  const premium = base + policyWideModifiers(base) + PROCESSING_FEE;
  return roundInMHPCOsFavour(premium);
}

